return $input.all().map(item => {
  const payload = item.json;
  const firstMedia = payload.items?.[0] || {};

  return {
    json: {
      format: payload.format || 'carousel',
      chat_id: payload.chat_id,
      internal_platform_id: payload.internal_platform_id,
      platform_user_id: payload.platform_user_id,
      access_token: payload.access_token,
      file_id: firstMedia.file_id || payload.file_id,
      incoming_type: firstMedia.type || payload.incoming_type || 'photo',
      caption: payload.caption || '',
      items: payload.items || [],
      draft_data: {
        target_platform: 'instagram',
        target_format: payload.format || 'carousel',
        items: payload.items || [],
        caption: payload.caption || ''
      }
    }
  };
});

const publishNodes = [
  '[Meta] Publish Reels',
  '[Meta] Publish Story',
  '[Meta] Publish Photo Post',
  '[Meta] Publish Carousel'
];

let platformPostId = null;

for (const nodeName of publishNodes) {
  try {
    const executedItems = $(nodeName).all();
    if (executedItems.length > 0 && executedItems[0].json?.id) {
      platformPostId = executedItems[0].json.id;
      break;
    }
  } catch (e) {}
}

// Извлекаем предупреждение, если карусель публиковалась с потерями
let warningMessage = null;
try {
  warningMessage = $('[Logic] Анализ готовности слайдов').first().json.warning || null;
} catch (e) {}

return [{
  json: {
    success: true,
    platform_post_id: platformPostId,
    warning: warningMessage
  }
}];

const items = $input.all();
const err = items[0]?.json || {};

function extractMetaMessage(e) {
  const direct =
    e?.details?.body?.error?.message ||
    e?.error?.response?.data?.error?.message ||
    e?.errorMessage;

  if (direct) {
    return String(direct);
  }

  const raw = e?.error?.message;

  if (typeof raw === 'string') {
    const idx = raw.indexOf('{');

    if (idx >= 0) {
      try {
        const parsed = JSON.parse(raw.slice(idx));

        if (parsed?.error?.message) {
          return parsed.error.message;
        }
      } catch (parseError) {
        // ignore
      }
    }

    return raw;
  }

  return '';
}

let message = extractMetaMessage(err) || 'Ошибка публикации в Instagram';

if (
  err?.details?.body?.error?.code === 9007 ||
  /Media ID is not available/i.test(message) ||
  /Медиаданные не готовы/i.test(message)
) {
  message = 'Медиаданные ещё не готовы к публикации. Попробуйте ещё раз через несколько секунд.';
}

return [{
  json: {
    success: false,
    error_message: message
  }
}];

