return $input.all().map(item => {
  const data = item.json;
  const slides = data.items || data.draft_data?.items || [];

  return {
    json: {
      chat_id: data.chat_id,
      internal_platform_id: data.internal_platform_id,
      platform_user_id: data.platform_user_id,
      access_token: data.access_token,
      items_count: slides.length,
      draft_data: {
        target_platform: 'instagram',
        target_format: 'carousel',
        items: slides,
        caption: data.caption || ''
      }
    }
  };
});

const draftDataItems = $('[DB] Загрузить контекст и токен').all();
if (!draftDataItems.length) return [];

const draft = draftDataItems[0].json;
const slides = draft.items || draft.draft_data?.items || [];

// Извлекаем message_id созданного сервисного статуса
const startStatus = $('[TG] Статус: Старт сборки').first()?.json;
const statusMessageId = startStatus?.message_id || startStatus?.result?.message_id;

return slides.map((slide, index) => ({
  json: {
    file_id: slide.file_id,
    type: slide.type,
    slide_index: index + 1,
    total_slides: slides.length,
    chat_id: draft.chat_id,
    access_token: draft.access_token,
    platform_user_id: draft.platform_user_id,
    caption: draft.caption || '',
    status_message_id: statusMessageId
  }
}));

const items = $input.all();

if (!items.length) {
  return [];
}

const hasError = items.some(item =>
  item.json.status_code === 'ERROR'
);

const allFinished = items.every(item =>
  item.json.status_code === 'FINISHED' || !item.json.status_code
);

const childIds = items
  .map(item => item.json.id)
  .filter(Boolean);

const access_token = $('[DB] Загрузить контекст и токен').all()[0]?.json?.access_token;
const statusMessageId = items[0]?.json?.status_message_id;

return [{
  json: {
    status: hasError
      ? 'ERROR'
      : allFinished
        ? 'FINISHED'
        : 'IN_PROGRESS',
    children: childIds.join(','),
    childIds,
    access_token,
    status_message_id: statusMessageId,
    attempt: ($runIndex || 0) + 1,
    finishedCount: items.filter(item =>
      item.json.status_code === 'FINISHED' || !item.json.status_code
    ).length,
    totalCount: items.length
  }
}];

const analysis = $('[Logic] Анализ готовности слайдов').first()?.json || {};
const ids = analysis.childIds || [];
const access_token = analysis.access_token || $('[DB] Загрузить контекст и токен').first().json.access_token;
const statusMessageId = analysis.status_message_id;

return ids.map(id => ({
  json: {
    id,
    access_token,
    status_message_id: statusMessageId
  }
}));

const items = $input.all();

const validSlides = [];
const rejectedSlides = [];

items.forEach((item, index) => {
  // Проверяем наличие ошибки от Meta или отсутствие ID контейнера
  if (item.json.error || !item.json.id) {
    const errorMsg =
      item.json.details?.body?.error?.error_user_msg ||
      item.json.details?.body?.error?.message ||
      item.json.error?.message ||
      'Неподдерживаемые пропорции или формат файла';

    rejectedSlides.push({
      slide_index: index + 1,
      error: errorMsg
    });
  } else {
    validSlides.push({
      id: item.json.id,
      slide_index: index + 1
    });
  }
});

// Проверка минимального контракта Meta для каруселей (минимум 2 слайда)
if (validSlides.length < 2) {
  const reasons = rejectedSlides.map(s => `Слайд #${s.slide_index}: ${s.error}`).join('; ');
  return [{
    json: {
      is_fatal_error: true,
      error_message: `Не удалось создать карусель: успешно создано слайдов — ${validSlides.length} (требуется минимум 2). Причины отклонения: ${reasons}`
    }
  }];
}

// Формируем текст предупреждения, если часть файлов была отсеяна
let warningText = null;
if (rejectedSlides.length > 0) {
  const rejectedIndexes = rejectedSlides.map(s => `#${s.slide_index}`).join(', ');
  warningText = `Серверы Meta отклонили ${rejectedSlides.length} файл(а) из-за неверных пропорций (слайды: ${rejectedIndexes}). Опубликованы только прошедшие проверку слайды (${validSlides.length} шт.).`;
}

// Пропускаем дальше только валидные контейнеры для опроса статуса
return validSlides.map(slide => ({
  json: {
    id: slide.id,
    slide_index: slide.slide_index,
    warning: warningText
  }
}));
